#include <Servo.h>

Servo esc;
const int escPin = 9; // Сигнал на ESC
const int buttonPin = 8; // Кнопка на D8
int motorSpeed = 0;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP); // Внутренняя подтяжка на 5V
  esc.attach(escPin, 1000, 2000); // Диапазон сигналов ESC: 1000мкс - 2000мкс
  esc.writeMicroseconds(1000); // Сигнал инициализации
  delay(3000); // Даем ESC время на калибровку
}

void loop() {
  if (digitalRead(buttonPin) == LOW) {
    motorSpeed = 1700; // Скорость вращения (1700 = около 75% мощи)
  } else {
    motorSpeed = 1000; // Остановка
  }
  esc.writeMicroseconds(motorSpeed);
}
